// Skip screening: pass articles through with default Maybe decision
const articles = $('Input').all().map(i => i.json);
console.log('Screening SKIPPED: ' + articles.length + ' articles passed through with decision=Maybe');
return articles.map(a => ({ json: { ...a, screening_decision: 'Maybe', screening_reason: 'Screening skipped by user', screening_color: 'orange' } }));

// SCREENING_REASON_PRISMA_v3
// SCREENING_REASON_PRISMA_v1
// SCREENING_CONFIDENCE_v1
// === SCREENING v3 - Prompt simplifie + batches reduits ===
// PATCH v2 : abstract-missing -> Maybe (no LLM call)
const items = $input.all();
const articles = items.map(i => i.json);
const BATCH_SIZE = 1;
const MIN_ABSTRACT_LEN = 50;  // < 50 chars = pas exploitable -> juge sur le titre seul
const question = (articles[0] && articles[0].question) || '';
const criteria = (articles[0] && articles[0].criteria) || '';
let aiSettings = (articles[0] && articles[0]._ai_settings) || {};
if (typeof aiSettings.strictness !== 'number') { try { const __ac = await this.helpers.httpRequest({ method:'GET', url:'http://host.docker.internal:8080/api/config', timeout:5000, json:true }) || {}; aiSettings = { strictness: __ac.screening_strictness, custom_rules: __ac.screening_custom_rules }; } catch(e) {} } // AI_SETTINGS_CONFIG_FALLBACK_v1
const strictness = (typeof aiSettings.strictness === 'number') ? aiSettings.strictness : 50;
const customRules = (aiSettings.custom_rules || '').toString().trim();
let strictnessGuidance = '';
if (strictness <= 25) {
  strictnessGuidance = '\n\n=== TONE GUIDANCE ===\nBe CONSERVATIVE: when in doubt, prefer Include or Maybe over Exclude. The user wants to capture as many potentially relevant articles as possible at this stage.';
} else if (strictness >= 75) {
  strictnessGuidance = '\n\n=== TONE GUIDANCE ===\nBe STRICT: only mark Include if all criteria are clearly met. When in doubt, prefer Exclude. The user wants a tightly filtered set of highly relevant articles.';
} else if (strictness >= 60) {
  strictnessGuidance = '\n\n=== TONE GUIDANCE ===\nBe slightly strict: when in doubt, lean toward Exclude rather than Maybe.';
} else if (strictness <= 40) {
  strictnessGuidance = '\n\n=== TONE GUIDANCE ===\nBe slightly conservative: when in doubt, lean toward Maybe rather than Exclude.';
}
const customRulesBlock = customRules
  ? '\n\n=== USER-DEFINED RULES (must be respected) ===\n' + customRules
  : '';
let batches = [];

// === A3 : LE MODELE JUGE LE TEXTE ENTIER, ET UNE COUPURE RESTANTE SE VOIT (2026-08-04) ===
// Le resume etait coupe a 800 caracteres, la question et les criteres a 500. MESURE sur un
// corpus reel de 8 135 resumes exploitables : 96,4 % depassaient 800 caracteres (mediane 1 732,
// maximum 29 155) et, pour 67,7 % des resumes structures, la section Results/Conclusions
// COMMENCE apres le 800e caractere. Le modele tranchait donc sans avoir lu le resultat de
// l'etude, et l'interface annoncait pourtant que tous les criteres etaient transmis.
//
// On ne coupe plus. Le contexte est calcule UNE SEULE FOIS pour le run, a partir du plus long
// prompt : le faire varier d'un article a l'autre ferait recharger les poids du modele a chaque
// changement de taille de fenetre, ce qui couterait bien plus que le gain.
const RESERVE_SORTIE = 4000;   // DOIT rester egal au num_predict du nœud d'appel
const CTX_PLANCHER = 6144;     // ce que l'ancienne version imposait a tout le monde
const CTX_PLAFOND = 16384;     // couvre 100 % du corpus mesure ; au-dela on coupe ET on le dit
const CTX_PAS = 2048;
const TITRE_MAX = 300;
// Estimation prudente : l'anglais tient en 4 caracteres par jeton, pas les resumes
// multilingues ni la terminologie medicale. Sous-estimer ferait deborder la fenetre, et un
// debordement se paie par la perte SILENCIEUSE du DEBUT du prompt, donc des criteres.
const _jetons = (n) => Math.ceil(n / 3) + 1;

function sanitize(text) {
  return (text || '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ').replace(/\s+/g, ' ').trim();
}

// PATCH v2 : pre-filtrer les articles SANS abstract exploitable.
// TITRE_SEUL_v1 : ils partent desormais au modele dans des lots a part, juges sur leur
// titre, avec interdiction d'inclure. Avant, ils sortaient en « Maybe » sans etre lus.
// On garde leur index global pour que Expand Results puisse les retrouver.
let llmEligibleCount = 0;
let skippedNoAbstract = 0;
for (let i = 0; i < articles.length; i++) {
  const abs = sanitize(articles[i].abstract || '');
  if (abs.length < MIN_ABSTRACT_LEN) {
    skippedNoAbstract++;
  } else {
    llmEligibleCount++;
  }
}
console.log('Screening v3 PATCH v2: ' + articles.length + ' articles total, ' +
            llmEligibleCount + ' avec abstract exploitable, ' +
            skippedNoAbstract + ' sans resume (-> juges sur le titre seul).');

// Generation des batches SEULEMENT pour les articles avec abstract exploitable.
// On stocke aussi la liste des global_indexes pour que Expand Results sache de quel article il s'agit.
let pendingBatch = [];
let pendingIndexes = [];
// TITRE_SEUL_v1 (2026-08-05). Ces references partaient en « Maybe » sans jamais etre
// lues : sur le corpus de l'utilisateur, 1 896 references sur 13 790 (13,7 %). Elles
// sont desormais jugees SUR LEUR TITRE, dans des lots separes pour que la consigne soit
// sans ambiguite, et le modele n'a le droit que d'exclure ou de douter.
let pendingTitre = [];
let pendingTitreIdx = [];

// === ULTRALAB_SCREENING_V4_TEXT - format reponse texte simple (anti batch failed) ===
// REASON_FORMAT_INSISTENCE_v7 - consigne 'no blank line' injectee dans le prompt
const batchesBruts = [];

function flushBatch() {
  if (pendingBatch.length === 0) return;
  batchesBruts.push({ articles: pendingBatch.slice(), indexes: pendingIndexes.slice(),
                      titreSeul: false });
  pendingBatch = [];
  pendingIndexes = [];
}

function flushTitre() {
  if (pendingTitre.length === 0) return;
  batchesBruts.push({ articles: pendingTitre.slice(), indexes: pendingTitreIdx.slice(),
                      titreSeul: true });
  pendingTitre = [];
  pendingTitreIdx = [];
}

function construirePrompt(liste, limiteResume, titreSeul) {
  // `limiteResume` a 0 signifie AUCUNE limite. Une limite n'est posee qu'en dernier recours,
  // quand le prompt entier ne tient pas dans le plafond de contexte, et elle est alors ECRITE
  // dans le texte transmis au modele comme sur l'article rendu.
  let coupeTotale = 0;
  const articleList = liste.map((a, j) => {
    const title = sanitize(a.title || 'No title').substring(0, TITRE_MAX);
    let abstract = sanitize(a.abstract || '');
    if (limiteResume > 0 && abstract.length > limiteResume) {
      const perdus = abstract.length - limiteResume;
      coupeTotale += perdus;
      abstract = abstract.substring(0, limiteResume)
        + ' [...tronque : ' + perdus + ' caracteres du resume non transmis]';
    }
    if (titreSeul) return 'TITLE: ' + title + '\nABSTRACT: (none available)';
    return 'TITLE: ' + title + '\nABSTRACT: ' + abstract;
  }).join('\n\n---\n\n');

  const prompt = 'You are a systematic review screener. Choose ONE decision for the article below: Include, Maybe, or Exclude.\n\n' +
    'RESEARCH QUESTION:\n' + sanitize(question) + '\n\n' +
    'INCLUSION/EXCLUSION CRITERIA:\n' + sanitize(criteria) + '\n\n' +
    '=== ARTICLE ===\n' + articleList + '\n\n' +
    (titreSeul
      ? '=== DECISION RULES (TITLE ONLY - NO ABSTRACT AVAILABLE) ===\n' +
        'You are given the TITLE only. The abstract could not be retrieved from any source.\n' +
        'You may answer ONLY "Exclude" or "Maybe". "Include" is FORBIDDEN here: a title alone\n' +
        'can never establish that every inclusion criterion is met.\n\n' +
        '- Exclude = the title ALONE makes it clear the record fails an inclusion criterion or\n' +
        '  meets an exclusion criterion (wrong population, wrong design, wrong topic, wrong\n' +
        '  publication type such as editorial, erratum, conference abstract, book review).\n' +
        '- Maybe = anything else. If the title is short, vague, or merely plausible: Maybe.\n\n' +
        'Do NOT guess the content. Exclude only on what the title actually states.'
      : '=== DECISION RULES ===\n' +
        '- Include = ALL inclusion criteria clearly met AND no exclusion criterion applies\n' +
        '- Maybe = at least one criterion is unclear from the abstract OR abstract is too brief\n' +
        '- Exclude = clearly fails at least one inclusion criterion OR clearly meets an exclusion criterion\n\n' +
        'When the abstract is missing or very short: ALWAYS choose Maybe.\n' +
        'When uncertain: Maybe (be inclusive at this stage).') + '\n\n=== LANGUAGE (MULTILINGUAL_SCREENING_v1) ===\nThe title/abstract may be written in a language other than English (French, Spanish, German, Portuguese, Italian, Chinese, etc.). Judge the study on its CONTENT, not its language. Do NOT Exclude an article merely because it is not written in English, UNLESS the inclusion/exclusion criteria explicitly restrict the language.' + strictnessGuidance + customRulesBlock + '\n\n' +
    '=== REASON REQUIREMENTS (PRISMA-grade, mandatory) ===\n- Name the SPECIFIC inclusion or exclusion criterion that drove the decision (quote the criterion).\n- Cite the concrete evidence FROM THE ABSTRACT that supports it: population, intervention/exposure, comparator, outcome, and/or study design as relevant.\n- If you Exclude, name the concrete disqualifier visible in the abstract (for example: it is a review or meta-analysis; it is a single-patient case report; it is an animal or preclinical study; the population is children; the primary indication is diabetes rather than obesity) and the abstract wording that proves it. If Maybe, state precisely what is missing or unclear in the abstract.\n- FORBIDDEN (not acceptable): vague or circular reasons such as: matches the criteria / clearly relevant / fits the research question / meets inclusion criteria / fails an inclusion criterion / clearly meets an exclusion criterion / fails at least one criterion. Repeating the rubric wording is NOT a reason. A reason that does not name the criterion AND point to abstract evidence is invalid.\n- Write the reason as ONE flowing sentence in plain natural-language PROSE (subject + verb). Do NOT use the Field=value format on the Reason line (the compact Field=value format is ONLY for the Criteria line). Keep it to 1-2 specific, auditable sentences on a SINGLE line.\n\n=== OUTPUT FORMAT (STRICT) ===\nOutput ONLY the following four lines, nothing before or after them. Begin with the word Decision.\nLine 1 = Decision: then your verdict, which is exactly one of Include, Maybe or Exclude.\nLine 2 = Reason: then ONE sentence that names the exact inclusion or exclusion criterion you applied AND states the concrete fact from the abstract above that triggered it (population, study design, intervention or outcome). Write Line 2 as a natural-language sentence in prose, NEVER as Field=value pairs; the Field=value format is reserved for Line 4 (Criteria).\nLine 3 = Confidence: then exactly one of high, medium or low. This line is mandatory and must never be omitted.\nLine 4 = Criteria: then a per-criterion audit of the inclusion and exclusion criteria, writing each criterion as a short label followed by = and one of met, unmet or unclear, separated by semicolons (for example Population=met; Study design=unmet; Outcome=unclear). Cover every criterion you can identify in the criteria text above. This line is required.\nDo NOT copy wording from these instructions or from the criteria list; describe only what THIS abstract actually says. The Reason must be consistent with the Decision (never write Exclude wording when the Decision is Include). No markdown, no numbering, no extra commentary.';

  return { prompt: prompt, coupe: coupeTotale };
}


for (let i = 0; i < articles.length; i++) {
  const abs = sanitize(articles[i].abstract || '');
  if (abs.length < MIN_ABSTRACT_LEN) {
    // TITRE_SEUL_v1 : lot separe, consigne separee. Un titre est un jugement possible,
    // pas un jugement impossible ; ce qui serait fautif, c'est de conclure a l'inclusion.
    pendingTitre.push(articles[i]);
    pendingTitreIdx.push(i);
    if (pendingTitre.length >= BATCH_SIZE) flushTitre();
    continue;
  }
  pendingBatch.push(articles[i]);
  pendingIndexes.push(i);
  if (pendingBatch.length >= BATCH_SIZE) flushBatch();
}
flushBatch();
flushTitre();

// === A3, assemblage : d'abord tous les prompts ENTIERS, pour connaitre le plus long. ===
// Le contexte du run s'en deduit, puis on ne rogne que ce qui depasse encore le plafond, et
// jamais la question ni les criteres : ce sont eux qui definissent la revue.
let besoinMax = 0;
// CADENCE_v1 : chaque lot porte l'intervalle d'emission des appels au modele, car c'est
// un parametre du nœud suivant et n8n le lit sur les elements qu'il recoit.
// UNE CADENCE ABSENTE N'EST PAS UN ZERO MESURE (2026-10-20, P05 de l'inventaire des defauts
// restants, verification du tour 1 du lot). Ce qui etait faux : l'absence donnait 0, et le repli
// prudent du nœud d'appel (1 800 ms) n'etait jamais atteint. MESURE (vrai routeur, vrai nœud, corps
// de lancement sans `pacing_ms`) : chaque appel au modele partait a 0 ms. Ce qui change : absente
// ou illisible, la cadence vaut null et le nœud d'appel prend son repli ; une cadence recue, zero
// compris, passe bornee a zero, comme avant.
const __cadence = parseInt((articles[0] || {})._pacing_ms, 10);
const _pacing = Number.isFinite(__cadence) ? Math.max(0, __cadence) : null;
const bruts = batchesBruts.map((b) => {
  const p = construirePrompt(b.articles, 0, !!b.titreSeul);
  const besoin = _jetons(p.prompt.length) + RESERVE_SORTIE;
  if (besoin > besoinMax) besoinMax = besoin;
  return { lot: b, p: p, besoin: besoin };
});
const numCtx = Math.min(CTX_PLAFOND,
  Math.max(CTX_PLANCHER, Math.ceil(besoinMax / CTX_PAS) * CTX_PAS));

let nCoupes = 0, carsCoupes = 0, nDebordent = 0;
for (let bi = 0; bi < bruts.length; bi++) {
  const e = bruts[bi];
  let p = e.p;
  if (e.besoin > numCtx) {
    const trop = (e.besoin - numCtx) * 3 + 96;   // marge, l'estimation est prudente mais pas exacte
    let leplus = 0;
    for (const a of e.lot.articles) {
      const n = sanitize(a.abstract || '').length;
      if (n > leplus) leplus = n;
    }
    p = construirePrompt(e.lot.articles, Math.max(400, leplus - trop), !!e.lot.titreSeul);
    if (_jetons(p.prompt.length) + RESERVE_SORTIE > numCtx) nDebordent++;
  }
  if (p.coupe > 0) { nCoupes++; carsCoupes += p.coupe; }
  batches.push({ json: {
    _pacing_ms: _pacing,
    _batch_kind: 'llm',
    prompt: p.prompt,
    num_ctx: numCtx,
    num_predict: RESERVE_SORTIE,
    _abstract_tronque: p.coupe,
    // A4 : la reprise doit juger avec la MEME severite et les MEMES regles.
    // Les blocs voyagent avec le lot, pour qu'il n'existe qu'un seul texte.
    _tone: strictnessGuidance,
    _rules: customRulesBlock,
    batchIndex: batches.length,
    batchSize: e.lot.articles.length,
    _titre_seul: !!e.lot.titreSeul,
    global_indexes: e.lot.indexes.slice()
  }});
}

console.log('Screening v3 PATCH v2: ' + batches.length + ' batches LLM construits, dont ' +
            batchesBruts.filter(function (b) { return b.titreSeul; }).length +
            ' lot(s) juges sur titre seul (' + skippedNoAbstract + ' references sans resume).');
console.log('Screening A3 : contexte du run = ' + numCtx + ' jetons (plancher ' + CTX_PLANCHER
  + ', plafond ' + CTX_PLAFOND + ', besoin du plus long prompt ' + besoinMax + ').');
if (nCoupes > 0) {
  console.log('Screening A3 : ' + nCoupes + ' resume(s) encore tronque(s) faute de contexte, '
    + carsCoupes + ' caracteres au total. La coupure est inscrite sur chaque article concerne.');
}
if (nDebordent > 0) {
  // Ce cas ne vient pas des resumes : c'est le bloc question + criteres qui, a lui seul, ne
  // tient pas. On le DIT, parce qu'un depassement se paie par la perte silencieuse du DEBUT du
  // prompt, donc precisement des criteres que l'utilisateur a saisis.
  console.log('Screening A3 : ATTENTION, ' + nDebordent + ' prompt(s) depassent encore le '
    + 'contexte apres troncature du resume. La question et les criteres sont trop longs pour '
    + 'le plafond de ' + CTX_PLAFOND + ' jetons : raccourcissez-les, sinon leur DEBUT sera perdu.');
}

// B6_NO_BATCH_v1 : si AUCUN abstract n'est exploitable (litterature grise ISRCTN/CT.gov, RIS
// sans resume), batches est vide. n8n SAUTE alors les nodes suivants : « Expand Results » ne
// tournait pas, le repli sans resume n'etait jamais applique et le run restait
// suspendu SANS resultat. On emet une sentinelle, routee AUTOUR de Call Ollama par le node
// IF « Has LLM Batch? », pour que la chaine aille toujours jusqu'au bout.
if (batches.length === 0) {
  console.log('Screening: aucun abstract exploitable -> sentinelle NO_LLM (contournement de Ollama).');
  return [{ json: {
    _pacing_ms: 0,
    _batch_kind: 'none',
    prompt: '',
    batchIndex: -1,
    batchSize: 0,
    global_indexes: [],
    _no_llm_reason: 'no_usable_abstract',
    _articles_total: articles.length
  }}];
}

// CACHE_SANS_ATTENTE_v2 : ne pas freiner ce qui ne coutera rien.
//
// L'intervalle d'emission protege le modele : envoyer plus vite qu'il ne repond fait enfler la
// file d'attente sans rien accelerer. Mais une reprise servie par le CACHE n'appelle pas le
// modele du tout. MESURE du 2026-08-10 sur le corpus de l'utilisateur : 12 772 references
// presque toutes deja repondues, 1,75 s par reference, six heures de projection pour un travail
// que le disque rend en quelques minutes.
//
// LA v1 POSAIT UN INTERVALLE NUL SUR CHAQUE LOT DEJA REPONDU. ELLE NE MARCHAIT PAS, et la
// mesure l'a montre sans appel : cent lots sur cent reconnus comme deja repondus, et le run
// toujours a 1,84 s par reference. Le nœud d'appel lit son intervalle UNE FOIS, pas element par
// element. Deux sondes en ligne de commande avaient semble dire le contraire ; elles etaient
// trop bruitees pour conclure, et c'est le systeme reel qui a tranche.
//
// LA v2 EN TIENT COMPTE. Un seul intervalle pour tout le run, proportionne a la part qui
// appellera VRAIMENT le modele :
//     intervalle = intervalle_mesure x (lots a calculer / lots au total)
// Le temps d'emission total vaut alors « lots a calculer x intervalle mesure », c'est-a-dire
// exactement le rythme auquel le modele sait repondre. Rien de plus, rien de moins.
//
// ET ON ENTRELACE. Un intervalle moyen ne protege que si les lots a calculer sont REPARTIS :
// s'ils arrivaient tous a la fin, ils se presenteraient a un rythme moyen bien plus rapide que
// le service et la file repartirait. On melange donc les deja-repondus et les autres. L'ordre
// n'a aucune importance ailleurs : chaque lot porte ses index d'origine (`global_indexes`), et
// l'etape suivante s'en sert pour remettre chaque decision sur son article.
//
// EN CAS D'ECHEC de la demande, tous les lots gardent l'intervalle mesure, c'est-a-dire le
// comportement d'avant : une optimisation ne doit jamais pouvoir casser un run.
try {
  // CADENCE_RAPPORTEE_v1 (2026-08-24). LE MODE PART AVEC LA DEMANDE.
  // Sans lui, le moteur calculait son intervalle nominal HORS CONTEXTE (une valeur de
  // repli de 1 800 ms) alors que la cadence mesuree pour ce modele et ce module valait
  // 1 367 ms, et il notait l'intervalle retenu sur le PREMIER run actif venu, qui
  // n'etait pas forcement celui-ci. Deux sources pour une meme grandeur, et une
  // estimation posee sur un run etranger.
  const _leMode = String((articles[0] || {})._module_mode || 'screening');
  if (batches.length > 1) {
    const _corps = batches.map(function (b) {
      return { prompt: b.json.prompt, num_ctx: b.json.num_ctx, num_predict: b.json.num_predict };
    });
    const _rep = await this.helpers.httpRequest({
      method: 'POST', url: 'http://host.docker.internal:8080/api/llm-cache/presence',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: _corps, mode: _leMode }), json: true, timeout: 120000
    });
    const _p = (_rep && _rep.presents) || [];
    if (_p.length === batches.length) {
      const _deja = [], _acalculer = [];
      for (let _i = 0; _i < batches.length; _i++) {
        (_p[_i] ? _deja : _acalculer).push(batches[_i]);
      }
      const _n = batches.length, _k = _acalculer.length;
      // L'INTERVALLE VIENT DU MOTEUR, il n'est plus calcule ici.
      //
      // Il l'etait des deux cotes : ici pour cadencer, et dans le registre des runs pour
      // estimer le temps d'emission restant. Les deux ont diverge des le premier ajustement.
      // MESURE du 2026-08-17 : la sonde avait trouve 12 772 invites sur 12 772 deja
      // repondues, donc un intervalle de 20 ms et moins de quatre minutes d'emission
      // restante ; le registre, qui estimait avec le nominal de 1 600 ms, a annonce
      // « 410 minutes » et termine l'execution. Le run allait ecrire son dossier partiel.
      //
      // Une seule formule, cote moteur (src/server.py, route de presence), et les deux
      // usages lisent la meme valeur. Le plancher qui protege le cas « tout en cache » y
      // vit aussi, avec son motif.
      const _inter = (_rep && _rep.intervalle_ms != null) ? _rep.intervalle_ms : _pacing;
      // Entrelacement : on place les lots a calculer aux positions les plus regulieres
      // possibles parmi les autres.
      const _ordre = [];
      let _ia = 0, _id = 0;
      for (let _i = 0; _i < _n; _i++) {
        const _du = Math.floor((_i + 1) * _k / _n) > Math.floor(_i * _k / _n);
        if (_du && _ia < _k) _ordre.push(_acalculer[_ia++]);
        else if (_id < _deja.length) _ordre.push(_deja[_id++]);
        else if (_ia < _k) _ordre.push(_acalculer[_ia++]);
      }
      batches = _ordre;
      for (let _i = 0; _i < batches.length; _i++) batches[_i].json._pacing_ms = _inter;
      console.log('Cadence : ' + _deja.length + ' invites deja repondues sur ' + _n +
                  ' -> un appel toutes les ' + _inter + ' ms (au lieu de ' +
                  (_pacing === null ? 'la cadence de repli du nœud d\'appel' : _pacing) + ').');
      // ON LE DIT AU MOTEUR, parce que personne ne peut le lire ici : les messages des
      // nœuds Code ne sortent pas du moteur de workflows dans cette configuration, et
      // l'execution n'enregistre ses donnees qu'a la fin. Un repli silencieux vers la
      // cadence nominale coute des heures sur une reprise servie par le cache ; il doit
      // etre VISIBLE a la premiere minute, pas devine apres coup.
      try {
        await this.helpers.httpRequest({
          method: 'POST', url: 'http://host.docker.internal:8080/api/cadence/appliquee',
          headers: { 'Content-Type': 'application/json' }, timeout: 8000,
          body: JSON.stringify({ mode: _leMode, intervalle_ms: _inter, nominal_ms: _pacing,
                                 lots: _n, deja_repondus: _deja.length })
        });
      } catch (__e) {}
    } else {
      console.log('Cadence : reponse de taille inattendue (' + _p.length + '/' +
                  batches.length + '), intervalle conserve partout.');
      // LE REPLI EST LE CAS COUTEUX : il rend au run la cadence nominale, c'est-a-dire
      // des heures d'attente sur un corpus deja repondu. Il doit crier, pas chuchoter.
      try {
        await this.helpers.httpRequest({
          method: 'POST', url: 'http://host.docker.internal:8080/api/cadence/appliquee',
          headers: { 'Content-Type': 'application/json' }, timeout: 8000,
          body: JSON.stringify({ mode: _leMode, intervalle_ms: _pacing,
                                 nominal_ms: _pacing, lots: batches.length,
                                 repli: 'reponse de taille inattendue' })
        });
      } catch (__e) {}
    }
  }
} catch (e) {
  console.log('Cadence : presence en cache non consultee (' + e.message +
              '), intervalle conserve partout.');
  try {
    await this.helpers.httpRequest({
      method: 'POST', url: 'http://host.docker.internal:8080/api/cadence/appliquee',
      headers: { 'Content-Type': 'application/json' }, timeout: 8000,
      body: JSON.stringify({ mode: String((articles[0] || {})._module_mode || 'screening'),
                             intervalle_ms: _pacing, nominal_ms: _pacing,
                             repli: 'presence non consultee : ' + e.message })
    });
  } catch (__e) {}
}

