// appel, et davantage sur un modele plus gros.
// MODELE : la reprise doit juger avec le modele de la passe principale, qui ne porte aucun tag.
// C'etait verifie en direct sous l'ancien tag 'chat' (gemma4:12b des deux cotes). Lu le
// 2026-09-30 dans src/proxy.py : le tag des reprises prend la meme valeur que 'chat' dans la
// table des tags (`_load_task_specific_models`) et recoit la meme surcharge de modele d'une
// relance ciblee (`_apply_model_override`).
// SIGNE DE VIE (2026-09-28, lot suivi) : le tag est desormais 'screening_retry'. Le relais le
// route vers le meme modele que 'chat', mais ne l'ecarte plus du signe de vie (src/proxy.py,
// SANS_COMPTE) : sous 'chat', aucune reprise ne prouvait que le run vivait, et la surveillance
// declare un run perdu apres 45 minutes sans avancement ni signe de vie. Une reprise ne fait
// toujours pas avancer la barre : l'article a ete compte par son premier appel.
async function retryOllamaCall(article, attempt, prepItem) {
  const ti = sanitize(article.title || '');
  const ab = sanitize(article.abstract || '');
  const cr = sanitize(criteria);
  const ton = (prepItem && prepItem._tone) || '';
  const regles = (prepItem && prepItem._rules) || '';
  const prompt = 'Article title: ' + ti + '\n' +
                 'Abstract: ' + ab + '\n\n' +
                 'Research question: ' + sanitize(question) + '\n\n' +
                 (cr ? 'Inclusion/exclusion criteria:\n' + cr + '\n\n' : '') +
                 ((ton || regles) ? (ton + regles).replace(/^\n+/, '') + '\n\n' : '') +
                 'Reply with ONLY these 2 lines (no explanation, no markdown):\n' +
                 'Decision: Include OR Maybe OR Exclude\n' +
                 'Reason: one short sentence\n\n' +
                 'Choose Maybe when uncertain. Start immediately with "Decision:".';

  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:3456/api/generate',
      body: JSON.stringify({
        model: 'llama3.2:latest',
        stream: false,
        // B8 : LA SECONDE TENTATIVE DOIT DIFFERER DE LA PREMIERE. Le decodage etait
        // glouton (temperature 0) et le prompt identique d'un essai a l'autre : mesure
        // faite, les deux appels a chaud sont identiques OCTET POUR OCTET, et le cache
        // du relais renvoie la meme reponse. Reessayer ne pouvait donc rien changer.
        // Meme remede que l'auto-coherence du relais : une graine distincte ET une
        // temperature non nulle, sans quoi la graine n'a aucun effet a temperature 0.
        // La cle du cache change alors d'elle-meme.
        options: { temperature: (attempt > 1 ? 0.7 : 0), seed: 4242 + attempt,
                   num_predict: 1500,
                   num_ctx: (prepItem && prepItem.num_ctx) || 6144 },
        keep_alive: '30m',
        prompt: prompt,
        _ultralab_task: 'screening_retry',
        // MODE DE L'APPELANT (2026-10-19) : le relais decide le refus d'un arret sur ce
        // mode, et non plus sur le dernier avancement ouvert (voir src/proxy.py).
        _ultralab_module: 'screening'
      }),
      headers: { 'Content-Type': 'application/json' },
      json: true,
      timeout: 180000
    });
    return resp && resp.response ? resp.response : '';
  } catch (e) {
    return '';
  }
}

// === BOUCLE PRINCIPALE : match response <-> article via prepBatches ===
const decisionByArticleIdx = new Map();
const rawByArticleIdx = new Map();
const retryStatsByArticleIdx = new Map();
let okBatches = 0, parseFailedBatches = 0, retrySuccessful = 0, retryFailed = 0;
const diagnostics = [];

for (let r = 0; r < responses.length; r++) {
  const resp = responses[r].json || {};
  const prepItem = prepBatches[r] && prepBatches[r].json ? prepBatches[r].json : {};
  const globalIndexes = Array.isArray(prepItem.global_indexes) ? prepItem.global_indexes : null;
  // A3 : ce que le prompt n'a PAS pu porter, pour que la coupure suive l'article.
  const _tronque = Number(prepItem._abstract_tronque || 0);
  const batchIdx = (resp.batchIndex !== undefined) ? resp.batchIndex : r;
  const batchSize = prepItem.batchSize || resp.batchSize || 1;

  const rawText = (resp.response || '').toString();
  let parsed = parseTextDecision(rawText);
  let attempt = 1;
  let lastRaw = rawText;

  // ARRET COOPERATIF (0.4.9) : quand l'utilisateur interrompt le run, le proxy cesse de servir
  // le modele et marque ses reponses. Sans ce garde, la boucle de reessai ci-dessous relancerait
  // DEUX appels par article restant, soit des heures de travail inutile juste apres une demande
  // d'arret. On note l'article comme NON TRAITE (pas de decision inventee) : il reste ainsi
  // detecte comme « en attente » par la reprise partielle, qui pourra le traiter plus tard.
  const _annule = !!resp.ultralab_cancelled;

  // Retry x2 si parse fail
  while (!_annule && !parsed && attempt <= RETRY_MAX && globalIndexes && globalIndexes.length === 1) {
    const articleIdx = globalIndexes[0];
    const article = articles[articleIdx];
    if (!article) break;
    const retryRaw = await retryOllamaCall.call(this, article, attempt, prepItem);
    lastRaw = retryRaw || lastRaw;
    parsed = parseTextDecision(retryRaw);
    attempt++;
    if (parsed) retrySuccessful++;
  }

  if (parsed) {
    okBatches++;
  } else {
    parseFailedBatches++;
    if (attempt > 1) retryFailed++;
  }

  // Mapping : pour BATCH_SIZE=1, globalIndexes a 1 element
  // Pour back-compat avec ancien BATCH_SIZE > 1, on supporte multiple
  if (globalIndexes && globalIndexes.length > 0) {
    // Pour le format texte simple, 1 batch = 1 article, donc 1 decision pour le seul article du batch
    const articleIdx = globalIndexes[0];
    rawByArticleIdx.set(articleIdx, {
      raw_preview: _annule ? '(run interrompu par l utilisateur)' : (lastRaw || 'no response').substring(0, 300),
      parse_status: _annule ? 'cancelled' : (parsed ? 'ok' : 'parse_failed'),
      attempt: attempt - 1,
      source: parsed ? parsed.source : 'no_parse',
      ambigu: !!(parsed && parsed.ambigu),
      tronque: _tronque
    });
    if (parsed) {
      decisionByArticleIdx.set(articleIdx, {
        decision: parsed.decision,
        reason: parsed.reason || '(no reason returned)',
        // AUDIT_ET_CERTITUDE_MISE_EN_FORME_v1 (2026-09-21). Ces deux lectures portent sur
        // l'article, a cote de la justification, ce que le modele a rendu. Elles ne
        // toleraient pas la mise en forme : vider une justification faite d'une seule
        // etiquette mise en forme laissait alors l'article entierement muet, ce que la
        // justification empechait avant ce lot puisqu'elle portait encore le texte.
        // MESURE RECOMPTEE LE 2026-09-23 SUR L'ETAT LIVRE, ce noeud au commit e912d7b contre
        // ce noeud, 14 formes fabriquees (listes CERTITUDE, AUDIT et VALEUR_EN_ITALIQUE du
        // fichier de cas) : 4 des 8 formes de certitude rendaient '' au lieu du niveau ecrit
        // (etoiles ou souligne autour du nom ou apres lui), 4 des 5 formes d'audit rendaient
        // une valeur polluee par la mise en forme ('** Population=met; Design=unmet') ou vide,
        // et la valeur en italique ne change pas. CE LOT CHANGE DONC DES VALEURS, 8 sur 14, et
        // pas seulement un texte : le niveau lu ici decide aussi du drapeau de relecture
        // humaine quand il vaut « low » (_needs_human_review, plus bas). La mise en forme est
        // donc admise autour du nom, comme dans la coupe de la justification.
        // L'ORDRE DES DEUX CLASSES APRES LES DEUX-POINTS EST MESURE, ET NON CHOISI : la
        // mise en forme d'abord, le blanc ensuite. Pris dans l'autre ordre, une valeur
        // ECRITE en italique perdrait son premier caractere ; mesure du meme jour,
        // « Criteria: *Population*=met » rend desormais l'audit intact. BORNE : ces deux
        // lectures ne sont pas ancrees a une frontiere de ligne, defaut anterieur a ce lot
        // et inchange par lui. LE RELAIS LIT LE MEME NIVEAU SANS TOLERER LA MISE EN FORME
        // (mesure du 2026-10-06). src/proxy.py, hors de ce lot, le lit aussi dans la reponse,
        // par deux lecteurs : _parse_screening_decision, dont le niveau « low » declenche le vote
        // d'auto-coherence quand le reglage screening_self_consistency l'active, et
        // _live_push_screening, le flux en direct. Ce noeud execute au commit e912d7b et sur
        // l'etat livre au tour 6, et ces deux lecteurs, sur 4 reponses fabriquees justifiees :
        // pour « **Confidence:** low », « **Confidence**: low » et « __Confidence:__ low », ce
        // noeud ne lisait rien au commit, pas plus que le relais, et lit desormais « low »,
        // drapeau de relecture pose, quand le relais ne lit toujours rien ; « Confidence: low »
        // est lu des deux cotes aux deux etats. Les aligner releve du lot qui tient src/. Cas :
        // tests/test_etiquette_mise_en_forme.py.
        confidence: (function(t){ var m = (t || '').match(/confidence[*_]*\s*[:=][*_]*\s*(high|medium|low)/i); return m ? m[1].toLowerCase() : ''; })(lastRaw),
        criteria: (function(t){ var m2 = (t || '').match(/criteria[*_]*\s*[:=][*_]*\s*([^\n]{0,1000})/i); return m2 ? m2[1].replace(/\s+/g, ' ').trim() : ''; })(lastRaw)
      });
    }
    // Pour les autres articles du batch (si jamais BATCH_SIZE > 1), enregistrer comme echec
    if (!parsed && globalIndexes.length > 1) {
      for (let k = 1; k < globalIndexes.length; k++) {
        const gi = globalIndexes[k];
        if (!rawByArticleIdx.has(gi)) {
          rawByArticleIdx.set(gi, {
            raw_preview: (lastRaw || 'no response').substring(0, 300),
            parse_status: 'parse_failed',
            attempt: attempt - 1,
            source: 'no_parse'
          });
        }
      }
    }
  } else {
    // Fallback : ordre sequentiel
    const fallbackIdx = batchIdx * batchSize;
    if (parsed && fallbackIdx < articles.length) {
      decisionByArticleIdx.set(fallbackIdx, {
        decision: parsed.decision,
        reason: parsed.reason || '(no reason returned)'
      });
    }
    rawByArticleIdx.set(fallbackIdx, {
      raw_preview: (lastRaw || 'no response').substring(0, 300),
      parse_status: parsed ? 'ok' : 'parse_failed',
      attempt: attempt - 1,
      source: parsed ? parsed.source : 'no_parse',
      ambigu: !!(parsed && parsed.ambigu)
    });
  }

  if (!parsed) {
    diagnostics.push('Article idx ' + (globalIndexes ? globalIndexes[0] : batchIdx * batchSize) +
      ' - parse failed after ' + (attempt - 1) + ' retries. Raw[0:120]: ' +
      lastRaw.substring(0, 120).replace(/\s+/g, ' '));
  }
}

// === Construction du resultat final ===
const results = [];
let totalInc = 0, totalExc = 0, totalMay = 0;
let skippedNoAbstract = 0;

for (let i = 0; i < articles.length; i++) {
  const article = articles[i];
  const abs = sanitize(article.abstract || '');
  const llmResult = decisionByArticleIdx.get(i);
  // DECISION_BRUTE_v1 (2026-08-25). LE VERDICT DU MODELE, AVANT TOUTE REECRITURE.
  //
  // Ce qui suit reecrit la decision dans quatre cas : article juge sur son seul titre et bride,
  // lot en echec replie sur « Maybe », resume absent, « Include » sans justification reclasse.
  // Ces reecritures sont justes -- ce sont des gardes scientifiques -- mais elles ne sont PAS
  // l'avis du relecteur.
  //
  // La mesure d'accord entre deux relecteurs comparait la decision reecrite : elle mesurait donc
  // l'accord du second relecteur avec NOS CORRECTIONS. On garde le verdict d'origine pour que
  // le kappa compare enfin deux avis. Chaine vide quand le modele n'a rien rendu : ce n'est pas
  // un avis, et cela ne doit pas entrer dans la mesure.
  const _decisionBrute1 = (llmResult && llmResult.decision) ? String(llmResult.decision) : '';
  let decision, reason;

  if (abs.length < MIN_ABSTRACT_LEN) {
    // TITRE_SEUL_v1 : le verdict rendu sur le titre est un vrai verdict, et il est
    // borne en amont a Exclude ou Maybe. On le borne aussi ICI : la consigne du prompt
    // est une demande, pas une garantie, et une inclusion decidee sur un titre seul
    // n'a aucune valeur probante.
    skippedNoAbstract++;
    if (llmResult && llmResult.decision === 'Exclude') {
      decision = 'Exclude';
      reason = 'Resume indisponible, juge sur le titre seul : ' + (llmResult.reason || '');
    } else if (llmResult) {
      decision = 'Maybe';
      reason = (llmResult.decision === 'Include'
        ? 'Resume indisponible : le modele proposait Include sur le titre seul, ramene a '
          + 'Maybe (un titre ne peut pas etablir tous les criteres). Motif rendu : '
        : 'Resume indisponible, juge sur le titre seul : ') + (llmResult.reason || '');
    } else {
      decision = 'Maybe';
      reason = abs.length === 0
        ? 'Resume absent et titre non juge (lot en echec) - Maybe par defaut'
        : 'Resume trop court (' + abs.length + ' chars) et titre non juge - Maybe par defaut';
    }
  } else if (llmResult) {
    decision = llmResult.decision;
    reason = llmResult.reason;
  } else {
    // Article cense etre traite par LLM mais pas de resultat (apres tous les retries)
    decision = 'Maybe';
    const rawInfo = rawByArticleIdx.get(i);
    let suffix = '';
    if (rawInfo) {
      const rp = (rawInfo.raw_preview || '').replace(/\s+/g, ' ').substring(0, 180);
      suffix = ' [retries: ' + (rawInfo.attempt || 0) + ' | LLM raw: ' + rp + ']';
    }
    reason = 'Batch LLM failed after retries - decision Maybe par defaut (a re-examiner manuellement)' + suffix;
  }


  // === INCLUDE_NEEDS_REASON_v1 - securite scientifique (2026-06-03) ===
  // Si le LLM a marque Include mais n'a pas fourni de justification verifiable,
  // on bascule en Maybe pour re-examen manuel (preserve la rigueur methodo).
  // DEUX ALTERNATIVES MORTES RETIREES (lot du 2026-09-21, mesure du 2026-10-06), « rien rendu »
  // et « blancs seuls », comme dans la garde du second relecteur (« Double Screen Kappa »). Ici,
  // decision ne vaut Include que par la branche du lecteur (le titre seul la borne a Exclude
  // ou Maybe, l'echec du lot a Maybe), et sa justification vaut ce que rend le lecteur ou
  // « (no reason returned) » a defaut : jamais vide. Le lecteur ne rend plus de justification
  // faite de blancs depuis que ses branches JSON appliquent la regle de vacuite de sa branche
  // texte (RAISON_JSON_VIDE_v1). Ce noeud execute sur 246 reponses fabriquees sans doublon (les
  // chaines a verdict de tests/test_etiquette_mise_en_forme.py a l'etat livre au tour 6 et 19
  // reponses degenerees), sans l'une,
  // sans l'autre, puis sans les deux : aucun champ ne change sur aucun article. Le meme noeud
  // au commit e912d7b : sans « blancs seuls », 6 articles changent (des reponses JSON dont la
  // justification s'ecrit vide ou en blancs, que cette alternative reclassait) ; sans « rien
  // rendu », aucun.
  if (decision === 'Include' && /^\(no reason|^\(no explicit/i.test(reason)) {
    decision = 'Maybe';
    reason = 'LLM a propose Include mais sans justification verifiable - reclasse Maybe pour verification manuelle';
  }
  if (decision === 'Include') totalInc++;
  else if (decision === 'Exclude') totalExc++;
  else totalMay++;

  // STATUT REEL DU TRAITEMENT (0.4.9), distinct de la DECISION.
  // Defaut corrige : ce node posait TOUJOURS une decision, y compris quand le modele n'avait
  // rien rendu (repli 'Maybe'). Deux consequences graves :
  //   - scientifiquement, un « Maybe » decide par le modele et un « Maybe » de repli apres
  //     echec etaient indiscernables dans les donnees ;
  //   - techniquement, la reprise partielle cherche les articles SANS decision : comme il y en
  //     avait toujours une, elle ne trouvait jamais rien et annoncait « tout est traite ».
  // On expose donc explicitement ce qui s'est reellement passe pour chaque article.
  // LECTURE_CONCLUSIVE_v1 : quand le verdict n'a pu etre lu que par la derniere occurrence
  // d'un mot dans une prose, la lecture est un pari, pas un constat. On ne le cache pas :
  // l'article part en relecture humaine et la regle employee est ecrite sur l'article.
  var _ric = rawByArticleIdx.get(i);
  var _lectureIncertaine = !!(_ric && _ric.ambigu);
  var _statut = 'ok';
  if (abs.length < MIN_ABSTRACT_LEN) {
    // Sans resume ET sans verdict, le lot a echoue : c'est un echec de lecture, pas une
    // fatalite, et la reprise partielle doit pouvoir le rejouer.
    _statut = llmResult ? 'no_abstract' : 'parse_failed';
  } else if (!llmResult) {
    var _ri = rawByArticleIdx.get(i);
    _statut = (_ri && _ri.parse_status === 'cancelled') ? 'cancelled' : 'parse_failed';
  }

  var _titreSeul = (abs.length < MIN_ABSTRACT_LEN && !!llmResult);
  results.push({
    json: {
      ...article,
      // La marque appartient a l'ARTICLE. Posee a cote de « json », elle faisait de
      // l'element une forme que le moteur de workflows refuse (« reserved key json »),
      // et le noeud entier echouait au premier article.
      _juge_sur_titre_seul: _titreSeul,
      screening_decision: decision,
      screening_decision_brute: _decisionBrute1,
      screening_reason: reason,
      screening_confidence: (llmResult && llmResult.confidence) || '',
      screening_criteria: (llmResult && llmResult.criteria) || '',
      _screening_status: _statut,
      _screening_parse_source: (_ric && _ric.source) || '',
      _screening_retry: (_ric && _ric.attempt) || 0,
      _screening_abstract_tronque: (_ric && _ric.tronque) || 0,
      _needs_human_review: (decision === 'Maybe') || !!(llmResult && llmResult.confidence === 'low') || _lectureIncertaine,
      screening_color: colorMap[decision] || 'orange'
    }
  });
}

console.log('=== Screening v4 ROBUST complete ===');
console.log('Articles: ' + results.length + ' | Batches OK: ' + okBatches + ' | Batches KO: ' + parseFailedBatches);
console.log('Retries reussis: ' + retrySuccessful + ' | Retries echoues: ' + retryFailed);
console.log('Sans resume, juges sur le titre seul : ' + skippedNoAbstract);
var _parRegle = {};
rawByArticleIdx.forEach(function(v){ var k = (v && v.source) || 'no_parse'; _parRegle[k] = (_parRegle[k] || 0) + 1; });
var _nTronques = 0, _carsTronques = 0;
rawByArticleIdx.forEach(function(v){ var t = (v && v.tronque) || 0; if (t > 0) { _nTronques++; _carsTronques += t; } });
if (_nTronques > 0) { console.log('Resumes encore tronques faute de contexte : ' + _nTronques + ' (' + _carsTronques + ' caracteres au total)'); }
console.log('Lecture des reponses : ' + Object.keys(_parRegle).sort().map(function(k){ return k + '=' + _parRegle[k]; }).join(' '));
console.log('Decisions: Include=' + totalInc + ' Maybe=' + totalMay + ' Exclude=' + totalExc);
if (diagnostics.length > 0) {
