// avales. Une declaration d'entree et de sortie change « le run s'est evapore »
// en « le run est entre ici et n'en est jamais ressorti ».
const __entree = (($input.all()[0] || {}).json) || {};
const __etMode = String(__entree._module_mode || 'screening');
