// quoi qu'il lui arrive : le contrat avec l'appelant ne change pas, et le corpus ne traverse
// jamais la frontiere entre sous-workflow et appelant (voir « Ecrire Corpus »).
const __sortieInchangee = $input.all();
const __corpusFichier = String(__entree._corpus_fichier || '');
const _fsd = require('fs');

// 1) Config double-relecture. LES MODELES SONT CEUX QUE LE RELAIS EMPLOIERA, pas ceux du
//    fichier de reglages.
//
//    DEFAUT MESURE : ce nœud lisait `ollama_model` et `screening_model_2`, deux reglages
//    LOCAUX, alors que le relais resout d'abord leurs equivalents DISTANTS. En mode distant,
//    un `remote_screening_model_2` vide faisait retomber la seconde passe sur le reglage local
//    pendant que la premiere employait `remote_ollama_model` : les deux relecteurs pouvaient
