  cfgOk = cfg.success === true;
} catch(e) { cfg = {}; cfgOk = false; }
const doubleEnabled = cfg.double_enabled === true;
const model1 = String(cfg.model_1 || '').trim();
const model2 = String(cfg.model_2 || '').trim();

// Garde : on NE relit pas. Chaque refus se nomme.
