// UNE PANNE N'EST PAS UN REGLAGE. Quand le moteur applicatif ne repond pas, on sortait par
// « disabled », exactement comme si l'utilisateur avait decoche la case : le motif affirmait un
// choix humain la ou il y avait une panne, et personne ne pouvait le savoir.
if (!cfgOk || !doubleEnabled || !model2 || model2 === model1) {
  const why = !cfgOk ? 'moteur_injoignable'
