}

// 2) Lecteur de decision : COPIE MOT POUR MOT de celui d'Expand Results.
// Les nœuds de code n8n ne partagent aucune fonction : la seule protection contre la derive
// entre les deux copies est un test qui extrait les deux et compare leur texte. Il existe,
// c'est tests/test_lecture_conclusive.py. Ne modifier ici que par recopie integrale.
// === PARSER TEXTE TOLERANT ===
// Cherche "Decision: <X>" puis "Reason: ...", avec multiples fallbacks.
//
// LECTURE_CONCLUSIVE_v1 (2026-08-04). Le repli lisait la PREMIERE occurrence de
// \b(Include|Maybe|Exclude)\b, donc le premier mot d'un raisonnement et non sa conclusion.
// Mesure avant correction, sur 15 sorties brutes : 5 lues a l'envers, dont
// « ... whether to Include or Exclude ... Therefore: Exclude. » rendu Include. Un modele qui
// raisonne enonce d'abord les options : le repli inversait alors systematiquement le tri.
// On lit desormais la conclusion, dans cet ordre : ligne ne portant que le verdict, verdict
// suivant une formule de conclusion, verdict en tete de texte, puis derniere occurrence. Ce
// dernier cas est un pari : il est marque `ambigu` pour partir en relecture humaine.
function parseTextDecision(raw) {
  if (!raw || typeof raw !== 'string') return null;
  const text = raw.trim();
  // RAISON_JSON_VIDE_v1 (lot du 2026-09-21, mesure du 2026-09-28). La regle de vacuite ne vivait
  // que dans la branche texte : une reponse JSON dont la justification ne porte que de la mise
  // en forme gardait cette mise en forme pour justification, et un Include passait la garde
  // « Include sans justification ». Ce noeud execute sur 13 reponses JSON fabriquees, avant et
  // apres : 6 Include rendaient Include et rendent Maybe ; 2 Include (justification faite de
  // blancs, ou liste vide) etaient deja Maybe par la garde du 2026-06-03 ; un Exclude et un
  // Maybe rendent la phrase d'une raison absente au lieu de la mise en forme ; les 3 temoins
  // (vraie justification, champ absent, nombre) ne changent pas. Une seule regle pour les
  // deux branches ; une valeur qui n'est pas du texte y est jugee sur son ecriture en texte
  // (une liste vide s'ecrit vide). Cas : tests/test_etiquette_mise_en_forme.py.
  const _seuleMiseEnForme = (r) => /^[\s>*_#-]*$/.test(String(r));

  // Tentative 1 : cherche "Decision: <X>" insensible a la casse
  const decMatch = text.match(/decision\s*[:=]\s*(include|maybe|exclude)/i);
  let decision = null, reason = '';
  if (decMatch) {
    decision = decMatch[1].charAt(0).toUpperCase() + decMatch[1].slice(1).toLowerCase();
    // Recuperer "Reason:" sur les lignes suivantes
    // BORNE DECLAREE (lot du 2026-09-21, mesure du 2026-09-28) : l'etiquette « Reason »
    // ELLE-MEME mise en forme n'est pas lue. Ce noeud execute sur 6 formes fabriquees portant
    // une vraie justification, au commit e912d7b comme apres : les 4 formes ou la marque suit
    // le nom (« **Reason**: ») perdent la justification et un Include y devient Maybe, les 2
    // formes ou elle entoure les deux-points (« **Reason:** ») gardent la marque en tete de la
    // justification. Les tolerer rendrait Include a ces 4 formes : decision laissee a
    // l'auteur. Cas BORNE de tests/test_etiquette_mise_en_forme.py.
    const reasonMatch = text.match(/reason\s*[:=](\s*)([\s\S]{0,2000})/i);
    if (reasonMatch) {
      // RAISON_VIDE_v1 (2026-09-12). Une ligne « Reason: » VIDE suivie de « Confidence: high »
      // donnait la justification « Confidence: high » : le blanc qui suit les deux-points avale
      // le saut de ligne, et la coupe ci-dessous n'agit que sur une etiquette en DEBUT de ligne.
      // Le saut de ligne avale lui est rendu : une etiquette qui ouvre la ligne suivante termine
      // une justification vide, et le noeud ecrit alors ce qu'il ecrit pour une raison absente,
      // « (no reason returned) ». Une justification sur la meme ligne, ou sur la ligne
      // suivante, se lit exactement comme avant.
      reason = ((/[\r\n]/.test(reasonMatch[1]) ? '\n' : '') + reasonMatch[2]).split(/\n\n|\r\n\r\n/)[0].replace(/[\r\n]+[\s>*_#-]*(confidence|decision|criteria|criterion)[*_]*\s*[:=][\s\S]*$/i, '').replace(/\s+/g, ' ').trim().substring(0, 2000);
      // ETIQUETTE_MISE_EN_FORME_v1 (2026-09-21). La coupe ci-dessus n'admettait, entre le saut
      // de ligne et le nom de l'etiquette, que des blancs : une etiquette MISE EN FORME devenait
      // donc la justification, et la garde « Include sans justification », plus bas, ne la
      // voyait pas. MESURE RECOMPTEE LE 2026-09-23 SUR L'ETAT LIVRE, ce noeud au commit e912d7b
      // contre ce noeud, 23 formes fabriquees portees par « Decision: Include » : celles des
      // listes FORMES, VACUITE_TRI, AUTRES_ETIQUETTES et BORNES_TRI du fichier de cas cite plus
      // bas, plus une ligne « Confidence: » et une ligne « Category: » sans mise en forme.
      // 17 rendaient Include et rendent desormais Maybe (etoile, tiret, diese, chevron ou
      // souligne, avant le nom de l'etiquette ou autour de lui ; justification faite de seule
      // mise en forme ; nom au singulier ; nom de la decision repete ; retour chariot seul). Les
      // 6 autres ne changent pas : la ligne « Confidence: » sans mise en forme rendait deja une
      // justification vide, la ligne « Category: » reste, le prompt du tri ne la demandant pas
      // (il demande quatre lignes : Decision, Reason, Confidence, Criteria), et les 4 formes de
      // BORNES_TRI sont la borne dite plus bas. CINQ temoins
      // mesures le meme jour arrivent entiers : meme ligne, ligne suivante, justification ouverte
      // par un tiret de liste, justification separee de l'etiquette par un trait, et le nom d'une
      // etiquette CITE AU MILIEU de la phrase. Ce cinquieme garde la coupe ANCREE a une frontiere
      // de ligne : mesure du 2026-09-21, une coupe desancree ne rendrait que 22 des 88 caracteres
      // de cette justification. La mise en forme est donc admise avant
      // le nom de l'etiquette et autour de lui, et une justification qui ne porte plus que de la
      // mise en forme est vide : le noeud ecrit alors ce qu'il ecrit pour une raison absente.
      // BORNE DE LA COUPE : elle n'admet, devant le nom de l'etiquette, que le blanc, le
      // chevron, l'etoile, le souligne, le diese et le tiret, et exige apres lui les
      // deux-points ou le signe egal. Parmi les formes jouees, restent la justification,
      // verdict Include garde au commit comme sur l'etat livre : les 4 formes de la liste
      // BORNES_TRI (recompte du 2026-09-23, ce noeud execute), une liste NUMEROTEE (« 1. » ou
      // « 2) »), une puce typographique et une etiquette separee de sa valeur par un tiret ;
      // et les 3 formes de la liste BORNES_CARACTERES_TRI (mesure du 2026-09-29, ce noeud
      // execute au commit e912d7b et sur l'etat livre), une puce « + », une etiquette entre
      // accents graves, et une justification faite de « + » seuls, que la regle de vacuite
      // ne connait pas ; et les 3 formes tri de la liste BORNES_MOT_DEVANT, une etiquette
      // precedee de mots : « Final decision: » (mesure du 2026-09-30, et du 2026-10-05 chez le
      // second relecteur : chacun des deux noeuds qui portent ce parseur execute au commit
      // e912d7b et sur l'etat livre), puis la syntaxe que le prompt du tri ecrit lui-meme,
      // « Line 3 = Confidence: », seule ou dans la copie des quatre lignes du prompt ; et les 8
      // formes tri des listes BORNES_MOT_APRES, BORNES_MEME_LIGNE et BORNES_SANS_MOT : un mot
      // entre le nom et les deux-points (« Confidence level: »), une etiquette nue ou mise en
      // forme ecrite sur la ligne meme de « Reason: », une justification faite de « N/A », d'un
      // tiret long, d'une puce ronde, de points de suspension ou d'une cloture de bloc de code.
      // Ces 10 formes, mesure du 2026-10-06, chacun des deux noeuds execute au commit e912d7b
      // et sur l'etat livre au tour 6 : Include garde chez le premier relecteur, aucun
      // signalement chez le second, l'etiquette ou le signe pour justification, aux deux
      // etats ; les couper est une decision laissee a l'auteur. Cette enumeration se borne aux
      // formes jouees : la garde n'est pas etanche, et l'etendre demanderait sa propre mesure
      // et son propre cas.
      // Mesure sur cas FABRIQUES seulement : la precision mesuree en 2026-09 sur 3 807 reponses
      // reelles du cache du relais n'a pas ete rejouee. Cas :
      // tests/test_etiquette_mise_en_forme.py.
      if (_seuleMiseEnForme(reason)) reason = '';
    }
      /* REASON_PROSE_CLEAN_v3 (2026-09-04) : LA COUPE AU PREMIER '=' EST SUPPRIMEE, PAS
         REMPLACEE. Mesure sur les 3 807 reponses reelles du cache du relais : elle s'est
         declenchee 41 fois et avait tort 40 fois, sur des effectifs et des tailles d'effet
         ecrits en prose (N=24, n=1,088, N = 13,775, d = 1.0, OR=1.615). Le 41e cas etait
         lui aussi une justification legitime, qui citait '(Population=met)' au milieu
         d'une phrase : la couper detruisait 263 de ses 339 caracteres. Precision mesuree
         de la regle : 1 sur 41.
         CE QU'ELLE COMPENSAIT est desormais fait proprement : 'criteria|criterion' est
         ajoute au strip de frontiere de ligne ci-dessus. Avec la fenetre a 2000, la sortie
         egale la ligne Reason entiere 3 807 fois sur 3 807, et aucun motif ne porte
         l'etiquette 'Criteria:'. */
    return { decision, reason, source: 'text_parse', ambigu: false };
  }

  // Tentative 2 : format JSON (back-compat), AVANT la lecture en prose.
  // Une reponse structuree fait autorite sur une chasse au mot-clef : quand le champ `reason`
  // precede le champ `decision`, la chasse lisait le verdict dans la justification.
  // Le decoupage non gourmand s'arretait a la PREMIERE accolade fermante : sur le format
  // { decisions: [ { ... } ] } il rendait un fragment invalide, donc cette branche etait morte.
  // On essaie le decoupage gourmand d'abord, le court ensuite.
  const _objets = [];
  const _g = text.match(/\{[\s\S]*\}/);
  const _c = text.match(/\{[\s\S]*?\}/);
  if (_g) _objets.push(_g[0]);
  if (_c && (!_g || _c[0] !== _g[0])) _objets.push(_c[0]);
  for (let _oi = 0; _oi < _objets.length; _oi++) {
    try {
      const parsed = JSON.parse(_objets[_oi]);
      if (parsed.decision) {
        const d = parsed.decision.toString().toLowerCase();
        if (d.startsWith('inc')) return { decision: 'Include', reason: _seuleMiseEnForme(parsed.reason) ? '' : (parsed.reason || ''), source: 'json_back_compat', ambigu: false };
        if (d.startsWith('exc')) return { decision: 'Exclude', reason: _seuleMiseEnForme(parsed.reason) ? '' : (parsed.reason || ''), source: 'json_back_compat', ambigu: false };
        if (d.startsWith('may')) return { decision: 'Maybe', reason: _seuleMiseEnForme(parsed.reason) ? '' : (parsed.reason || ''), source: 'json_back_compat', ambigu: false };
      }
      // Ancien format { decisions: [{...}] }
      if (Array.isArray(parsed.decisions) && parsed.decisions.length > 0) {
        const d = parsed.decisions[0];
        const dec = (d.decision || '').toString().toLowerCase();
        let dn = 'Maybe';
        if (dec.startsWith('inc')) dn = 'Include';
        else if (dec.startsWith('exc')) dn = 'Exclude';
        return { decision: dn, reason: _seuleMiseEnForme(d.reason) ? '' : (d.reason || ''), source: 'json_legacy_back_compat', ambigu: false };
      }
    } catch (e) {}
  }

  // Tentative 3 : aucune structure. Le modele a redige, sa conclusion est a la FIN.
  //
  // Le contenu d'un bloc de reflexion n'est pas une reponse : on le retire avant de chercher.
  // S'il ne reste aucun verdict visible, on rend null pour declencher la reprise, plutot que
  // de prelever un mot au milieu d'une deliberation.
  // L'ordre compte : un bloc de reflexion NON FERME (reponse tronquee) doit disparaitre en
  // entier AVANT qu'on efface les balises isolees, sinon il ne reste plus de balise ouvrante
  // a reconnaitre et toute la deliberation redevient lisible comme si c'etait la reponse.
  const zone = text.replace(/<(think|thinking|reasoning)>[\s\S]*?<\/\1>/gi, ' ')
                   .replace(/<(think|thinking|reasoning)>[\s\S]*$/i, ' ')
                   .replace(/<\/?(think|thinking|reasoning)>/gi, ' ')
                   .trim();
  const VERDICT = /\b(include|maybe|exclude)\b/i;
  if (!VERDICT.test(zone)) return null;

  const _nu = (s) => String(s || '').replace(/[*_`~#>\[\]()"'.,;:!?\-\s]+/g, ' ').trim();
  const _cap = (s) => String(s).charAt(0).toUpperCase() + String(s).slice(1).toLowerCase();
  const _prose = (s) => String(s || '').replace(/^[\s:.,;*_`>\-]+/, '').replace(/[\s*_`>\-]+$/, '').replace(/\s+/g, ' ').trim();

  let trouve = null, regle = '', pos = -1, ambigu = false;

  // (a) la derniere ligne porteuse de sens ne contient QUE le verdict.
  const lignes = zone.split(/\r?\n/);
  for (let li = lignes.length - 1; li >= 0; li--) {
    if (!/[A-Za-z0-9]/.test(lignes[li])) continue;         // ligne vide, cloture de bloc, ponctuation
    if (/^(include|maybe|exclude)$/i.test(_nu(lignes[li]))) {
      trouve = _nu(lignes[li]); regle = 'ligne_verdict'; pos = zone.lastIndexOf(lignes[li]);
      const dedans = lignes[li].match(VERDICT);
      if (dedans) pos = zone.lastIndexOf(lignes[li]) + lignes[li].indexOf(dedans[0]);
    }
    break;                                                  // on ne juge QUE la derniere ligne utile
  }

  // (b) un verdict dans la fenetre qui suit une formule de conclusion, la derniere du texte.
  if (!trouve) {
    const MARQ = /(final answer|answer is|answer\s*[:=]|in conclusion|conclusion\s*[:=]?|therefore|thus|hence|verdict\s*[:=]?|my decision|my answer|i (?:would|will|'d) (?:choose|select|go with|say)|en conclusion|donc|par consequent|par conséquent|ma decision|ma décision)/gi;
    let mm, gagnant = null, gagnantPos = -1, plusieurs = false;
    while ((mm = MARQ.exec(zone)) !== null) {
      const debut = mm.index + mm[0].length;
      // La fenetre est la PHRASE qui porte la conclusion, pas un nombre de caracteres arbitraire :
      // « Therefore I cannot Include it without knowing the design; Maybe. » se conclut apres le
      // point-virgule. Coupee trop tot, la fenetre ne voyait que la negation.
      let fenetre = zone.substring(debut, debut + 200);
      const finPhrase = fenetre.search(/[.!?](\s|$)|\n/);
      if (finPhrase >= 0) fenetre = fenetre.substring(0, finPhrase + 1);
      const tous = fenetre.match(/\b(include|maybe|exclude)\b/gi) || [];
      if (!tous.length) continue;
      const distincts = new Set(tous.map((x) => x.toLowerCase()));
      gagnant = tous[tous.length - 1];
      gagnantPos = debut + fenetre.toLowerCase().lastIndexOf(gagnant.toLowerCase());
      plusieurs = distincts.size > 1;
    }
    if (gagnant) { trouve = gagnant; regle = 'formule_conclusive'; pos = gagnantPos; ambigu = plusieurs; }
  }

  // (c) le texte OUVRE sur le verdict : la conclusion est en tete, la prose qui suit la motive.
  if (!trouve) {
    const decale = zone.length - zone.replace(/^[\s*_`#>\-]+/, '').length;
    const mt = zone.substring(decale).match(/^(include|maybe|exclude)\b/i);
    if (mt) { trouve = mt[1]; regle = 'verdict_en_tete'; pos = decale; }
  }

  // (d) plus rien de fiable : on prend la DERNIERE occurrence, et on le declare.
  if (!trouve) {
    const toutes = zone.match(/\b(include|maybe|exclude)\b/gi) || [];
    if (!toutes.length) return null;
    trouve = toutes[toutes.length - 1];
    regle = 'derniere_occurrence';
    pos = zone.toLowerCase().lastIndexOf(trouve.toLowerCase());
    ambigu = true;
  }

  // Justification : ce qui suit le verdict, sinon ce qui le precede (une conclusion vient apres
  // son motif). A defaut, un texte que le garde « Include sans justification » sait reconnaitre.
  // REPLI_SANS_ETIQUETTES_v1 (lot du 2026-09-21, mesure du 2026-09-28). Cette branche gardait
  // les ETIQUETTES dans la justification : une reponse Include dont la ligne « Reason: » est
  // vide et suivie d'etiquettes, ou suivie d'une seule ligne d'etiquette, restait Include avec
  // « Reason: Confidence: high » pour justification, et la garde « Include sans justification »
  // ne le voyait pas. On arrive ici quand l'etiquette « Decision » est mise en forme (la
  // Tentative 1 ne la lit pas) ou absente (verdict en tete ou en derniere ligne). Sont donc
  // retirees les lignes qui OUVRENT par une etiquette du prompt du tri autre que Reason
  // (meme classe de mise en forme devant le nom que la coupe de la Tentative 1, deux-points
  // ou signe egal exiges), l'etiquette Reason est retiree de la ligne qu'elle ouvre, et une
  // justification faite de seule mise en forme est vide. Une etiquette citee AU MILIEU d'une
  // ligne n'est pas touchee. Mesure du 2026-09-28, ce noeud execute sur les reponses
  // fabriquees des listes REPLI et TEMOINS_REPLI de tests/test_etiquette_mise_en_forme.py,
  // etat livre au tour 3 contre ce noeud : les 14 reponses de REPLI rendaient Include
  // (comme au commit e912d7b) et rendent Maybe ; les 13 temoins gardent leur decision
  // et leur drapeau, et 7 d'entre eux perdent les etiquettes qui polluaient leur
  // justification. BORNE : une etiquette « Decision » mise en forme est toujours lue ici, par
  // la derniere occurrence d'un verdict, drapeau d'ambiguite pose ; un verdict cite dans le
  // motif y est donc pris pour la decision (cas BORNE du fichier cite, identique au commit).
  // La rendre lisible par la Tentative 1, remede mesure le meme jour sur les memes reponses,
  // rendrait Maybe une reponse justifiee dont l'etiquette Reason porte sa mise en forme apres
  // le nom (la Tentative 1 ne lit pas cette etiquette, borne declaree plus haut), retirerait
  // le drapeau de 2 reponses justifiees, laisserait Include 10 des
  // 14 reponses de REPLI et corrigerait 1 verdict lu dans le motif : decision laissee
  // a l'auteur. Cas fabriques seulement.
  const _sansEtiquettes = (s) => String(s || '').split(/\r\n|\r|\n/)
    .filter((l) => !/^[\s>*_#-]*(confidence|decision|criteria|criterion)[*_]*\s*[:=]/i.test(l))
    .map((l) => l.replace(/^[\s>*_#-]*reason[*_]*\s*[:=][*_]*/i, ''))
    .join('\n');
  let just = _prose(_sansEtiquettes(pos >= 0 ? zone.substring(pos + trouve.length) : ''));
  if (just.length < 8) just = _prose(_sansEtiquettes(zone.substring(0, Math.max(0, pos)).slice(-2000)));
  if (_seuleMiseEnForme(just)) just = '';
  reason = just ? just.substring(0, 2000) : '(no explicit reason field in the raw response)';

  return { decision: _cap(trouve), reason, source: 'fallback_' + regle, ambigu };
}

// LA JUSTIFICATION DU SECOND RELECTEUR ETAIT EXTRAITE PUIS JETEE (2026-08-24).
//
// `parseTextDecision` rend une decision ET son motif ; on ne gardait que la decision. Sur un
// desaccord, l'arbitre humain se retrouvait donc devant deux verdicts nus : « Include contre
// Exclude », sans savoir POURQUOI. Or c'est le motif qui permet de trancher, pas le verdict.
function parseDec(raw){
  const p = parseTextDecision(raw);
  return p ? { decision: p.decision, reason: p.reason || '' } : null;
}

// TEMOIN_SECONDE_RELECTURE_v1 (2026-08-26). ON DIT QU'ON TRAVAILLE ENCORE.
//
// Le corpus est ecrit AVANT ce nœud, et le registre du moteur applicatif tient le corpus pour
// la preuve qu'un run est fini. Sans ce temoin, un run a double relecture serait declare
// termine avant le premier appel de la seconde passe : l'assemblage produirait rapport et
// exports sur les seules decisions de la premiere passe, l'utilisateur corrigerait des
// decisions a la main dans un dossier qu'il croit fini, et la reecriture finale de ce nœud
// les effacerait.
const __temoin = __corpusFichier ? (__corpusFichier + '.seconde-relecture') : '';
function __poserTemoin() {
  if (!__temoin) return;
  try { _fsd.writeFileSync(__temoin, String(Date.now()), 'utf-8'); } catch (e) {}
}
function __retirerTemoin() {
  if (!__temoin) return;
  try { _fsd.unlinkSync(__temoin); } catch (e) {}
}

// 3) 2e passe : re-jouer les memes invites avec le modele 2 (tag screening_pass2).
//
// LES DECISIONS DE LA PREMIERE PASSE SONT RELUES DEPUIS LE NŒUD QUI LES A PRODUITES. Elles ne
// transitent plus par l'entree, qui ne porte que le chemin du corpus. La branche « tri saute »
// n'a pas de premiere passe a relire : on ne fait rien, et c'est correct.
let pass1 = [];
try { pass1 = $('Expand Results').all().map(i => i.json); } catch (e) { pass1 = []; }
if (!pass1.length) {
  console.log('Double screening SKIP (aucune premiere passe a relire)');
  return __sortieInchangee;
}

// LES INVITES NE SONT RECUPEREES QU'ICI, c'est-a-dire une fois la garde franchie
// (2026-08-25). Elles l'etaient plus haut, AVANT la garde : le nœud materialisait donc
// les 12 772 elements de l'etape precedente, portant chacun plusieurs kilo-octets
// d'invite, soit une centaine de mega-octets, pour les jeter aussitot dans le cas
// courant ou la double relecture est desactivee.
const prep = $('Prepare Batches').all().map(i => i.json); // invites + index d'origine

const dec2ByIdx = new Map();
let nCalls = 0, nCallFail = 0, nAbandons = 0;

// UN APPEL ABANDONNE N'EST PAS UN APPEL SERVI. Le relais rend un HTTP 200 portant
// `ultralab_timeout` (son plafond d'attente atteint) ou `ultralab_cancelled` (arret demande),
// SANS champ `response`. Le compteur d'appels reussis les comptait comme des succes : l'article
// perdait son second avis, et rien nulle part ne le disait.
async function __unAvis(p) {
  const resp = await this.helpers.httpRequest({
    method:'POST', url:'http://host.docker.internal:3456/api/generate',
    // LE BUDGET DE SORTIE EST CELUI DE LA PREMIERE PASSE. Il valait 2 000 ici contre 4 000 la,
    // alors que « Prepare Batches » ecrit noir sur blanc : RESERVE_SORTIE = 4000, « DOIT rester
    // egal au num_predict du nœud d'appel ». Le second relecteur travaillait avec la moitie du
    // budget du premier : ses reponses longues etaient coupees, donc illisibles, donc comptees
    // comme une absence d'avis. Deux relecteurs qui n'ont pas le meme budget ne repondent pas a
    // la meme question.
    body: JSON.stringify({ model: model2, stream:false, options:{ temperature:0, stop:['\n\n\n','Article ','TITLE:','Article:'], num_predict:4000, num_ctx:(p.num_ctx || 6144) }, keep_alive:'30m', prompt: p.prompt, _ultralab_task:'screening_pass2', _ultralab_module:'screening' }),
    headers:{ 'Content-Type':'application/json' }, json:true, timeout:600000
  });
  if (resp && (resp.ultralab_timeout || resp.ultralab_cancelled)) return { abandon:true, raw:'' };
  return { abandon:false, raw:(resp && resp.response) ? resp.response : '' };
}

// LES APPELS PARTENT A PLUSIEURS, DANS LA LIMITE DES PLACES DU POSTE DE MODELES. Un emetteur
// qui ATTEND sa reponse ne peut pas faire enfler la file : la borne de simultaneite suffit, et
// c'est pourquoi il n'y a pas d'intervalle ici, contrairement au nœud d'appel de la premiere
// passe qui, lui, n'attend pas.
__poserTemoin();
const __places = Math.max(1, Math.min(8, Number(cfg.places || 1)));
const __travail = [];
for (let r = 0; r < prep.length; r++) {
  const p = prep[r] || {};
  const gi = (Array.isArray(p.global_indexes) && p.global_indexes.length) ? p.global_indexes[0] : null;
  if (gi === null || !p.prompt) continue;
  __travail.push({ gi: gi, p: p });
}
let __curseur = 0;
async function __ouvrier() {
  while (true) {
    const k = __curseur++;
    if (k >= __travail.length) return;
    const t = __travail[k];
    let raw = '';
    try {
      const r = await __unAvis.call(this, t.p);
      if (r.abandon) { nAbandons++; continue; }
      raw = r.raw; nCalls++;
    } catch(e) { nCallFail++; continue; }
    const d = parseDec(raw);
    if (d && d.decision) dec2ByIdx.set(t.gi, d);
  }
}
