// seconde passe -- on detruirait la premiere pour avoir voulu ajouter la seconde.
let __reecrit = false;
if (__corpusFichier) {
  const __tmp = __corpusFichier + '.part';
  try {
    const __f = _fsd.openSync(__tmp, 'w');
    _fsd.writeSync(__f, '[');
    for (let i = 0; i < out.length; i++) {
      const __o = (i === 0) ? Object.assign({}, out[i], { screening_double:'on', _screening_kappa: summary })
                            : Object.assign({}, out[i], { screening_double:'on' });
      _fsd.writeSync(__f, (i ? ',' : '') + JSON.stringify(__o));
    }
    _fsd.writeSync(__f, ']');
    _fsd.closeSync(__f);
    _fsd.renameSync(__tmp, __corpusFichier);
    __reecrit = true;
    console.log('Corpus reecrit avec la seconde relecture : ' + __corpusFichier);
  } catch (e) {
    // LA PREMIERE PASSE RESTE INTACTE SUR LE DISQUE. C'est tout l'objet de l'ordre nouveau :
    // un echec ici coute le second avis, jamais le premier.
    console.log('Reecriture du corpus impossible (' + e.message + ') : la premiere passe reste en place');
    try { _fsd.unlinkSync(__tmp); } catch (e2) {}
  }
}

return $input.all().map(function (it) {
  return { json: Object.assign({}, it.json, { _double_relecture: __reecrit ? 'on' : 'echec_ecriture',
                                              _double_resume: summary }) };
});
} catch (__err) {
  // AUCUNE EXCEPTION NE DOIT COUTER LA PREMIERE PASSE. Elle est deja sur le disque ; le nœud
  // rend son entree inchangee, et l'assemblage termine le dossier comme si la seconde relecture
  // n'avait jamais ete demandee.
  console.log('Seconde relecture abandonnee (' + (__err && __err.message) + ') : la premiere passe est intacte');
  return $input.all();
} finally {
  // LE TEMOIN PART PAR TOUS LES CHEMINS. Laisse en place apres une exception, il bloquerait
  // la cloture du run indefiniment : la protection deviendrait la panne.
  try { __retirerTemoin(); } catch (e) {}
  await __etape.call(this, 'sortie', null);
}

// CORPUS_PAR_FICHIER_v1 (2026-08-25). LE CORPUS NE TRAVERSE PLUS LA FRONTIERE.
//
// MESURE QUI L'IMPOSE : pendant le tri, le moteur de workflows tient a 1,45 Gio ; en
// quelques secondes, au moment ou les 12 772 articles passent de ce sous-workflow a son
// appelant, il monte a 2,49 Gio et meurt avec « JavaScript heap out of memory ». Le moteur
// RECOPIE les elements a ce passage : le corpus est tenu DEUX FOIS.
//
// Ni l'ecriture (corrigee avant, gain reel mais insuffisant) ni le plafond de tas (essaye a
// 2 048 puis 2 560 Mo) n'y suffisent. La machine n'offre que 3,94 Go a la machine virtuelle.
//
// On ecrit donc le corpus ici, et on ne rend qu'un chemin. L'assemblage le relit : une copie
// au lieu de deux.
//
// LE REPLI EST INTEGRAL : si l'ecriture echoue, ou si le dossier n'est pas sous une racine
// autorisee, on rend les articles comme avant. Un correctif de memoire ne doit jamais
// pouvoir faire perdre un resultat.
const _fs = require('fs');
const _elements = $input.all();
const _a0 = (_elements[0] && _elements[0].json) || {};
const _dossier = String(_a0.output_folder || '');

// La meme garde de chemin que partout ailleurs : sous le Bureau ou sous un dossier de
// projet, et pas de remontee de repertoire.
function _autorise(p) {
  const s = String(p || '');
  if (!s || s.indexOf('..') >= 0) return false;
  return s.indexOf('/desktop/') === 0 || s.indexOf('/projets/') === 0;
}

if (!_autorise(_dossier)) {
  console.log('Corpus non ecrit (dossier hors des racines autorisees), on rend les articles');
  return _elements;
}
try {
  _fs.mkdirSync(_dossier, { recursive: true });
  const _cible = _dossier + '/articles-full.json';
  _fs.writeFileSync(_cible, JSON.stringify(_elements.map(function (i) { return i.json; })), 'utf-8');
  console.log('Corpus ecrit (' + _elements.length + ' articles) : ' + _cible);
  return [{ json: {
    _corpus_fichier: _cible,
    _corpus_n: _elements.length,
    // L'assemblage lit ces trois champs sur son PREMIER element : ils doivent voyager.
    _module_mode: _a0._module_mode,
    output_folder: _a0.output_folder,
    _folder_name: _a0._folder_name
  } }];
} catch (e) {
  console.log('Ecriture du corpus impossible (' + e.message + '), on rend les articles');
  return _elements;
}
